with valid_products as (select *, length(product_name) as product_name_length from products where (product_name like 'Y%' and stock_qty = 142) or stock_qty < 181), brand_summary as (select brand, category, max(cost) as max_cost, avg(stock_qty) as avg_stock_qty from valid_products group by brand, category) select * from brand_summary where avg_stock_qty >= 380 order by max_cost desc
